import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\x0c')
for i, page in enumerate(pages, 1):
    if 'References' in page:
        # Check if it's a section header
        for line in page.split('\n'):
            stripped = line.strip()
            if stripped == 'References' or stripped.startswith('References'):
                print(f'Page {i}: \"{stripped}\"')
    if 'Limitations' in page:
        for line in page.split('\n'):
            if 'Limitations' in line and ('imitation' in line.lower()):
                print(f'Page {i}: \"{line.strip()}\"')
    if i <= 2:
        continue
    # Look for Appendix as section header
    for line in page.split('\n'):
        stripped = line.strip()
        if stripped.startswith('A ') and ('Hyperparameters' in stripped or 'Loss' in stripped):
            print(f'Page {i} appendix: \"{stripped}\"')
        if stripped.startswith('B ') and ('Loss' in stripped or 'Iteration' in stripped):
            print(f'Page {i} appendix: \"{stripped}\"')
"

